 import unittest
from candidate import derivative

class TestDerivative(unittest.TestCase):
    def test_derivative_positive_coefficients(self):
        self.assertEqual(derivative([3, 1, 2, 4, 5]), [1, 4, 12, 20])

    def test_derivative_single_coefficient(self):
        self.assertEqual(derivative([1]), [])

    def test_derivative_negative_coefficients(self):
        self.assertEqual(derivative([-3, -1, -2, -4, -5]), [-1, -4, -12, -20])

    def test_derivative_zero_coefficient(self):
        self.assertEqual(derivative([0]), [])

    def test_derivative_empty_list(self):
        self.assertEqual(derivative([]), [])

    def test_derivative_floats_coefficients(self):
        self.assertListEqual(derivative([1.5, 2.3, 3.7]), [2.3, 7.4])

    def test_derivative_mixed_coefficients(self):
        self.assertEqual(derivative([1, 2, 0, 4]), [2, 0, 12])

if __name__ == '__main__':
    unittest.main()
